//! Oracle: `svelters_compiler::svelte::parse::parse` against real `svelte/compiler` 5.57.2
//! `parse(source, { modern: true, loose })` (target/oracle/svelte.jsonl, generated by
//! tools/oracle/gen.mjs). See tests/oracle_common/mod.rs for the comparison rules.
//!
//! `cargo test -p svelters-compiler --release --test oracle_svelte -- --nocapture`

mod oracle_common;

use oracle_common::*;
use serde_json::{json, Value};
use svelters_compiler::svelte::parse::{parse, ParseOptions};

fn expected_ok(case: &Value) -> Value {
    let mut e = case["ast"].clone();
    normalize(&mut e, Suite::Svelte);
    e
}

/// Compares our successful parse (serialized, BYTE offsets) with the corpus.
fn compare_ok(case: &Value, mut ours: Value, map: &Utf16Map) -> Outcome {
    if !case["error"].is_null() {
        let e = &case["error"];
        return Outcome::ErrorMismatch(format!("expected error {} {:?} at {}, ours parsed", e["code"], e["message"].as_str().unwrap_or(""), e["start"]));
    }
    bytes_to_utf16(&mut ours, map);
    normalize(&mut ours, Suite::Svelte);
    match diff(&expected_ok(case), &ours) {
        None => Outcome::Pass,
        Some(d) => Outcome::AstMismatch(d),
    }
}

/// Compares our CompileError (`start` in BYTES): code, message and start must match.
fn compare_err(case: &Value, code: &str, message: &str, start: u64, map: &Utf16Map) -> Outcome {
    let e = &case["error"];
    if e.is_null() {
        return Outcome::ErrorMismatch(format!("expected AST, ours failed: {code} {message:?} at byte {start}"));
    }
    let ours_start = map.convert(start);
    let (ec, em) = (e["code"].as_str().unwrap_or(""), e["message"].as_str().unwrap_or(""));
    if ec == code && em == message && e["start"].as_u64().is_some() && e["start"].as_u64() == ours_start.as_u64() {
        Outcome::Pass
    } else {
        Outcome::ErrorMismatch(format!("expected {ec} {em:?} at {}, ours {code} {message:?} at {ours_start}", e["start"]))
    }
}

fn precheck(case: &Value) -> Result<(&str, ParseOptions), Outcome> {
    if let Some(s) = case["skip"].as_str() {
        return Err(Outcome::Skipped(s.to_string()));
    }
    if case["error"]["crash"] == true {
        return Err(Outcome::Skipped("upstream threw a non-CompileError".into()));
    }
    let opts = ParseOptions { loose: case["options"]["loose"] == true, native: false };
    Ok((case["source"].as_str().expect("case.source"), opts))
}

fn run_case(case: &Value) -> Outcome {
    let (src, opts) = match precheck(case) {
        Ok(x) => x,
        Err(o) => return o,
    };
    let map = Utf16Map::new(src);
    let r = guarded(|| match parse(src, &opts) {
        Ok(root) => Ok(serde_json::to_value(&root).expect("serialize Root")),
        Err(e) => Err((e.code, e.message, e.start as u64)),
    });
    match r {
        Err(o) => o,
        Ok(Ok(ours)) => compare_ok(case, ours, &map),
        Ok(Err((code, msg, start))) => compare_err(case, code, &msg, start, &map),
    }
}

#[test]
fn oracle_svelte() {
    let Some(cases) = load_corpus("svelte") else { return };
    let cases = filter_cases(cases);
    let report = run_suite(Suite::Svelte, &cases, run_case);
    finish(&report);
}

/// Harness self-test: every corpus expectation, with its offsets turned into byte offsets, goes
/// through the same path as our parser's output and must compare equal.
#[test]
fn oracle_svelte_selftest_roundtrip() {
    let Some(cases) = load_corpus("svelte") else { return };
    let results = parallel_map(&cases, |case| {
        let (src, _) = match precheck(case) {
            Ok(x) => x,
            Err(_) => return (Outcome::Pass, false),
        };
        let map = Utf16Map::new(src);
        let back = ByteMap::new(src);
        let to_bytes = |u: u64| Value::from(back.to_byte(u).unwrap_or_else(|| panic!("{}: utf16 {u} inside a surrogate pair", case["id"])));
        let o = if case["error"].is_null() {
            let mut ours = case["ast"].clone();
            map_offsets(&mut ours, &to_bytes);
            compare_ok(case, ours, &map)
        } else {
            let e = &case["error"];
            let start = to_bytes(e["start"].as_u64().unwrap()).as_u64().unwrap();
            compare_err(case, e["code"].as_str().unwrap(), e["message"].as_str().unwrap(), start, &map)
        };
        (o, !src.is_ascii())
    });
    let non_ascii = results.iter().filter(|r| r.1).count();
    let bad: Vec<String> = results
        .iter()
        .zip(&cases)
        .filter(|((o, _), _)| !matches!(o, Outcome::Pass))
        .map(|((o, _), c)| format!("{}: {}", c["id"], o.detail()))
        .collect();
    println!("svelte self-test: {} cases round-tripped, {non_ascii} with non-ASCII source", cases.len());
    assert!(bad.is_empty(), "round trip failed for {} cases:\n{}", bad.len(), bad[..bad.len().min(20)].join("\n"));
    assert!(non_ascii > 10, "corpus should exercise non-ASCII sources");
}

#[test]
fn svelte_ignore_list() {
    let mut e = json!({
        "type": "Root", "start": 0, "end": 10, "js": [],
        "css": {"type": "StyleSheet", "start": 0, "end": 5, "attributes": [], "children": [{"type": "Rule"}], "comments": [],
                "content": {"start": 1, "end": 2, "styles": "a{}", "comment": null}},
        "options": {"start": 0, "end": 1, "attributes": [], "customElement": {"tag": "x-a"}},
        "fragment": {"type": "Fragment", "nodes": [{"type": "RegularElement", "name": "p", "name_loc": {}, "metadata": {},
            "attributes": [], "fragment": {"type": "Fragment", "nodes": []}, "start": 0, "end": 1}]},
        "instance": {"content": {"body": [{"type": "VariableDeclaration", "leadingComments": [], "trailingComments": []}]}}
    });
    normalize(&mut e, Suite::Svelte);
    let want = json!({
        "type": "Root", "start": 0, "end": 10,
        "css": {"type": "StyleSheet", "start": 0, "end": 5, "attributes": [], "content": {"start": 1, "end": 2, "styles": "a{}"}},
        "options": {"start": 0, "end": 1, "attributes": []},
        "fragment": {"type": "Fragment", "nodes": [{"type": "RegularElement", "name": "p",
            "attributes": [], "fragment": {"type": "Fragment", "nodes": []}, "start": 0, "end": 1}]},
        "instance": {"content": {"body": [{"type": "VariableDeclaration"}]}}
    });
    assert!(diff(&want, &e).is_none(), "{:?}", diff(&want, &e));
    // a non-empty `js` is not ignored
    let mut e = json!({"type": "Root", "js": [1]});
    normalize(&mut e, Suite::Svelte);
    assert!(e.get("js").is_some());
}
